import { createServer } from 'node:http';

import { playerPage } from './page.js';

const MAX_EVENT_BYTES = 64 * 1024;

/**
 * Serves the SDK page to the WKWebView and takes its events back.
 *
 * This port is a trust boundary, not an implementation detail: the page is
 * handed a live Spotify access token. `secret` is generated by the daemon
 * and travels only in the URL given to the player process, so a local
 * process that scans the port range gets 403 instead of a token.
 *
 * `getToken` lets the page pick up a refreshed access token; without it the
 * server just hands out the token it was started with.
 */
export function startHttpServer({ token, getToken, deviceName, onEvent, secret }) {
  const currentToken = getToken ?? (async () => token);

  return new Promise((resolve, reject) => {
    const server = createServer((req, res) => {
      const url = new URL(req.url, `http://127.0.0.1`);

      const deny = () => {
        res.writeHead(403);
        res.end();
      };

      // A browser lured here by DNS rebinding carries the attacker's
      // hostname; a loopback client never does.
      const host = req.headers.host ?? '';
      if (host && !/^(127\.0\.0\.1|\[::1\]|localhost)(:\d+)?$/.test(host)) return deny();

      if (secret && url.searchParams.get('k') !== secret) return deny();

      if (req.method === 'POST' && url.pathname === '/event') {
        let body = '';
        let tooBig = false;

        req.on('data', (chunk) => {
          body += chunk;
          if (body.length > MAX_EVENT_BYTES) {
            tooBig = true;
            req.destroy();
          }
        });

        req.on('end', () => {
          if (tooBig) return;
          try {
            const { kind, data } = JSON.parse(body);
            onEvent(kind, data);
            res.writeHead(204);
            res.end();
          } catch {
            // A malformed event is the page's problem, not the daemon's.
            res.writeHead(400);
            res.end();
          }
        });
        return;
      }

      if (url.pathname === '/player') {
        currentToken()
          .then((t) => {
            res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
            res.end(playerPage(t, deviceName, secret));
          })
          .catch(() => {
            res.writeHead(500);
            res.end();
          });
        return;
      }

      if (url.pathname === '/token') {
        currentToken()
          .then((t) => {
            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ token: t }));
          })
          .catch(() => {
            res.writeHead(500);
            res.end();
          });
        return;
      }

      res.writeHead(404);
      res.end();
    });

    server.on('error', reject);

    server.listen(0, '127.0.0.1', () => {
      const { port } = server.address();
      resolve({
        port,
        url: `http://127.0.0.1:${port}/player${secret ? `?k=${secret}` : ''}`,
        close: () => new Promise((done) => server.close(done)),
      });
    });
  });
}
